    "domanda": "Leggere il brano e rispondere alla seguente domanda. Centro CONI Il Centro CONI è il progetto nazionale del CONI che ridisegna il modo di fare sport durante il pomeriggio. Non un solo sport, ma tante attività sportive che i giovani - di età compresa fra i 5 e i 14 anni - possono scoprire e praticare ampliando così il personale bagaglio motorio e affinando i gesti tecnici specifici relativi alle diverse discipline coinvolte. Parola d’ordine: contaminazione! Il CONI e gli Organismi Sportivi attraverso le società sportive ad essi affiliate e i propri tecnici hanno deciso di “mettersi in gioco” e di cogliere la sfida facendo “rete”, di unire le proprie conoscenze specifiche per costruire insieme un percorso di crescita sportiva che ponga al centro i giovani atleti, che sia coinvolgente e stimolante e che faciliti, allo stesso tempo, lo sviluppo delle loro abilità e competenze. Tutti i partecipanti al Centro CONI possono praticare le attività sportive secondo percorsi che tengono conto delle loro fasi di crescita psico-fisica con una frequenza minima di 2 volte a settimana presso le società sportive coinvolte. «Lo sport (…) alla vita un maggiore equilibrio psicofisico e l’arricchisce di serenità e coraggio» Gabriella Dorio - La Parola d’ordine del progetto è:",
