    "id": 217,
    "domanda": "Leggere il brano e rispondere alla seguente domanda. Il nuovo impianto di tiro con la balestra prevede: in fondo al campo di tiro una parete concava di altezza minima, dalla base alla sommità, mt. 10; sviluppo minimo in altezza di mt. 12; larghezza minima della parete mt. 15. Durante gli allenamenti, i bersagli devono essere posti ad almeno 4 metri di distanza dalla parete; la distanza tra ciascun bersaglio deve essere al minimo di mt. 3; è fortemente raccomandata la distanza di mt. 3,20. Durante le competizioni, i bersagli devono essere posti ad almeno 4,5 metri di distanza dalla parete e la distanza tra ciascun bersaglio deve essere esattamente di mt. 4. La larghezza della parete dovrà consentire la sistemazione, durante le gare, di almeno tre bersagli. Ufficiali di gara verificheranno le distanze. Agli Ufficiali di gara è fatto obbligo di indossare appositi giubbetti di protezione, berretto con la visiera con la scritta \"Ufficiale di gara\" ed occhiali protettivi nell'eventualità che dal bersaglio si stacchino schegge. Se non vengono rispettate le distanze, la competizione sarà invalidata e l'Ufficiale inadempiente deferito alla Commissione di disciplina. - Secondo il brano:",
