    "domanda": "Leggere il brano e rispondere alla seguente domanda. La nuova palestra ha abbattuto il concetto di palestra con il format innovativo del villaggio fitness e una concezione di benessere che si basa su divertimento, famiglia, amici e offerta All Inclusive. Il centro offre oltre 200 macchinari per l'allenamento, 3 sale (gialla, rossa, verde) per i corsi fitness, piscina da 25 metri per il nuoto e i corsi in acqua, area relax con sauna, bagno turco e idromassaggio. Il club sta effettuando lavori che permetteranno agli abbonati di usufruire, per il marzo 2021, di un centro estetico e per il giugno dello stesso anno di un centro per le acconciature e il trucco per spose. Nella sala gialla si effettuano corsi di pilates in tre fasce orarie: la mattina dalle 10.00 alle 12.00, il pomeriggio dalle 16.00 alle 18.00, la sera dalle 20.00 alle 22.00; nella sala rossa si effettuano corsi di step in tre fasce orarie: la mattina dalle 11.00 alle 13.00, il pomeriggio dalle 15.00 alle 18.00, la sera dalle 19.00 alle 21.00; nella sala verde si effettuano corsi di pump in tre fasce orarie: la mattina dalle 12.00 alle 14.00, il pomeriggio dalle 17.00 alle 18.00, la sera dalle 20.00 alle 22.00. La mattina i corsi sono frequentati prevalentemente da anziani, il pomeriggio da studenti e la sera da lavoratori. Tutti gli abbonamenti prevedono la formula All Inclusive, i servizi del club sono inclusi nella quota mensile senza alcun costo aggiuntivo e senza limitazione di orario. Gli unici servizi extra, non accessibili agli ingressi giornalieri (non abbonati), sono il personal training, le lezioni di nuoto individuali e il servizio di babysitting per i bimbi dai 6 ai 18 mesi. La quota mensile è uguale per tutti, ma chi paga per un anno ha diritto ad uno sconto del 30%. La palestra propone offerte vantaggiose per gli studenti dai 14 ai 26 anni e per gli anziani, che devono però accedere al club rispettivamente entro le 16.00 e entro le 11.00 e uscire trascorse due ore dall'entrata, mentre non hanno alcuna limitazione di orario durante il fine settimana. Per i più piccoli (sino a 13 anni di età) per attivare l'abbonamento è necessaria la presenza di un genitore, o chi ne fa le veci, iscritto al club ed è previsto lo stesso sconto per gli abbonamenti annuali. È possibile effettuare degli ingressi giornalieri che permettono di partecipare a qualsiasi attività sia in sala che in piscina e di usufruire di tutta l'area benessere. Ogni ingresso costa 25 euro. - Gli anziani che usufruiscono di offerte vantaggiose:",
