    "domanda": "Il rafforzamento democratico, moderato e occidentale nel dopoguerra italiano avvenne anche di riflesso alla politica internazionale dove l'avvio della guerra fredda accentuò le fratture nel sistema politico italiano. Se i comunisti rimasero fedeli a Mosca, cosa successe tra i socialisti?",
